mapper.select:
SELECT cfg.id AS id, cfg.ds_id AS dsId, cfg.ds_name AS dsName, cfg.system_code AS systemCode, cfg.db_type AS dbType, cfg.jdbc_url AS jdbcUrl, cfg.driver_class AS driverClass, cfg.readonly_user AS readonlyUser, cfg.readonly_password_ref AS readonlyPasswordRef, cfg.owner_group AS ownerGroup, cfg.space_name AS spaceName, cfg.space_names AS spaceNamesJson, cfg.whitelist_json AS whitelistJson, cfg.limits_json AS limitsJson, cfg.status AS status, cfg.remark AS remark, cfg.version AS version, cfg.create_time AS createTime, cfg.update_time AS updateTime, cfg.is_deleted AS isDeleted, adm.manage_state AS manageState, adm.space_bind_state AS spaceBindState, adm.space_bind_error AS spaceBindError, adm.last_health_state AS lastHealthState, adm.last_health_time AS lastHealthTime FROM t_ds_config cfg INNER JOIN t_ds_config_admin adm ON adm.ds_id = cfg.ds_id AND adm.is_deleted = 0
AND cfg.is_deleted = 1
AND cfg.is_deleted = 0
AND adm.manage_state = #{query.manageState}
AND cfg.system_code = #{query.systemCode}
AND cfg.db_type = #{query.dbType}
AND cfg.space_name = #{query.spaceName}
AND (cfg.ds_name LIKE CONCAT('%', #{query.keyword}, '%') OR cfg.ds_id LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY cfg.update_time DESC, cfg.id DESC
